using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Experimental.Rendering;

namespace Game.Rendering.Pixel
{
    /// <summary>
    /// A district/time palette (MODULARITY §4.7, F-046): the colour list of one palette_set@v1 profile plus the haze,
    /// sky, grading and dither parameters and the baked LUT. Assets are generated by PaletteProfileGenerator from
    /// Config/Rendering/palette_set.json and PaletteProfileTuning.json; a new palette is a new asset (duplicate, edit,
    /// "Bake LUT"), never a code or shader change.
    /// </summary>
    public sealed class PaletteProfile : ScriptableObject
    {
        [Header("Identity (palette_set@v1)")]
        public string profileId = "";
        public string paletteSet = PixelContractVersions.PaletteSet;
        [Tooltip("SHA-256 of the colour list as compact JSON (lowercase #rrggbb, declared order). Written by Bake.")]
        public string paletteSha256 = "";

        [Header("Colours (declared order = palette index)")]
        public Color32[] colours = Array.Empty<Color32>();
        public PaletteRole[] roles = Array.Empty<PaletteRole>();
        public int accentIndex = -1;
        [Tooltip("Haze ramp, near-dark to far-light (R-002 ramp_uniform_L). Scene value 0..1 is graded along it.")]
        public Color32[] hazeRamp = Array.Empty<Color32>();

        [Header("Haze (bands evenly spaced in log distance, see HazeMath)")]
        [Tooltip("Distance (m) below which there is no haze.")]
        public float hazeStartM = 60f;
        [Tooltip("Distance (m) beyond which everything is pure airlight (the last band).")]
        public float hazeFullM = 20000f;
        [Tooltip("Shape of the haze curve: level = pow(t, gamma) with t the log-distance fraction. 1 = pure log spacing; below 1 lifts near levels.")]
        public float hazeCurveGamma = 1f;
        [Tooltip("Number of haze bands; 0 = one band per ladder rung. The last band is pure airlight.")]
        public int hazeBands = 0;

        /// <summary>The number of haze bands in use: hazeBands, or one per ladder rung when hazeBands is 0.</summary>
        public int HazeBandCount => hazeBands > 0 ? hazeBands : Mathf.Max(2, ladder != null && ladder.Length >= 2 ? ladder.Length : 8);
        [Tooltip("T-190 far lift (flag rendering.pixel.hazeFarLift): distance (m) beyond which the haze level is pushed up toward pure airlight; 0 = no lift.")]
        public float hazeFarStartM = 0f;
        [Tooltip("T-190 far lift: distance (m) at which the lifted level reaches the last band (pure airlight).")]
        public float hazeFarFullM = 0f;
        [Tooltip("T-190 far lift: exponent of the lift fraction w = (ln(d / start) / ln(full / start))^power; below 1 lifts faster.")]
        public float hazeFarPower = 1f;
        [Tooltip("Half width of the dithered seam at a band boundary, in texels measured along the surface. A face at one distance gets no seam.")]
        public float hazeSeamTexels = 3f;
        [Tooltip("Largest width of a seam in bands (keeps a seam inside its two bands where distance changes fast).")]
        public float hazeSeamWidth = 0.7f;
        [Tooltip("Scene-space value (sRGB grey, 0..1) of the airlight; 1 grades to the light end of the ramp.")]
        public float airlightValue = 1f;

        [Header("Sky (drawn by the haze stage where there is no geometry)")]
        public float skyHorizonValue = 1f;
        public float skyZenithValue = 0.6f;
        [Tooltip("Elevation (degrees) at which the sky reaches the zenith value.")]
        public float skyZenithElevationDeg = 30f;

        [Header("Grade (baked into the LUT)")]
        public float valueScale = 1f;
        public float valueBias = 0f;
        public float valueGamma = 1f;
        public float accentChromaStart = 25f;
        public float accentChromaFull = 60f;

        [Header("Dither")]
        [Tooltip("1 = dither across the whole step between two palette colours, 0 = hard nearest colour.")]
        [Range(0f, 1f)] public float ditherSpread = 0.4f;
        [Tooltip("Smallest step of scene value (sRGB units) between neighbouring texels of one surface that counts as a gradient. Faces flatter than this take one palette colour.")]
        public float ditherGradientMin = 0.001f;
        [Tooltip("Weight of chroma against lightness when the LUT picks palette entries (1 = plain OKLab). Above 1 keeps neutral scene tones on the ramp's own hue.")]
        public float lutChromaWeight = 1f;
        [Tooltip("Value ladder for neutral tones: smallest L* step between two rungs (0 = no ladder, every palette entry may be used).")]
        public float ladderMinStepL = 0f;
        [Tooltip("Value ladder: how far (CIELAB a*, b*) an entry may sit from the haze ramp's colour of the same lightness and still be a rung.")]
        public float ladderHueTolerance = 12f;
        [Tooltip("Value ladder: lightness (L*) of the top rung; 0 = the light end of the haze ramp.")]
        public float ladderTopL = 0f;
        [Tooltip("Palette indices of the ladder rungs, dark to light. Written by Bake.")]
        public int[] ladder = Array.Empty<int>();
        public float pairPenalty = 0.25f;
        public int lutCandidates = 5;

        [Header("Baked LUT (R-003 §3)")]
        public int lutSize = 32;
        [HideInInspector] public byte[] lut = Array.Empty<byte>();
        public string lutSha256 = "";

        [NonSerialized] Texture3D m_LutTexture;
        [NonSerialized] Texture2D m_PaletteTexture;
        [NonSerialized] string m_TextureLutSha, m_TexturePaletteSha;   // the hash strings the textures were built from (compared by reference: no per-frame allocation)

        public const int PaletteTextureWidth = 256;

        public bool IsBaked => lut != null && lut.Length == lutSize * lutSize * lutSize * PaletteLutBaker.BytesPerCell && colours.Length > 0;

        public Rgb8[] ColourList()
        {
            var list = new Rgb8[colours.Length];
            for (int i = 0; i < list.Length; i++) list[i] = new Rgb8(colours[i].r, colours[i].g, colours[i].b);
            return list;
        }

        public Rgb8[] HazeRampList()
        {
            var list = new Rgb8[hazeRamp.Length];
            for (int i = 0; i < list.Length; i++) list[i] = new Rgb8(hazeRamp[i].r, hazeRamp[i].g, hazeRamp[i].b);
            return list;
        }

        public PaletteLutInput ToLutInput() => new PaletteLutInput
        {
            Colours = ColourList(), ValueRamp = HazeRampList(), AccentIndex = accentIndex, Size = lutSize,
            ValueScale = valueScale, ValueBias = valueBias, ValueGamma = valueGamma,
            AccentChromaStart = accentChromaStart, AccentChromaFull = accentChromaFull,
            PairPenalty = pairPenalty, Candidates = lutCandidates, ChromaWeight = lutChromaWeight,
            LadderMinStepL = ladderMinStepL, LadderHueTolerance = ladderHueTolerance, LadderTopL = ladderTopL,
        };

        /// <summary>Copies the colour data of a palette_set@v1 profile into this asset (tuning fields are left alone).</summary>
        public void SetData(PaletteProfileData data)
        {
            profileId = data.Id;
            paletteSet = PixelContractVersions.PaletteSet;
            colours = new Color32[data.Colours.Count];
            roles = data.Roles.ToArray();
            for (int i = 0; i < colours.Length; i++) colours[i] = new Color32(data.Colours[i].R, data.Colours[i].G, data.Colours[i].B, 255);
            hazeRamp = new Color32[data.RampUniform.Count];
            for (int i = 0; i < hazeRamp.Length; i++) hazeRamp[i] = new Color32(data.RampUniform[i].R, data.RampUniform[i].G, data.RampUniform[i].B, 255);
            accentIndex = data.AccentIndex;
        }

        /// <summary>Bakes the LUT and the hashes from the current colours and parameters.</summary>
        [ContextMenu("Bake LUT")]
        public void Bake()
        {
            var input = ToLutInput();
            lut = PaletteLutBaker.Bake(input);
            ladder = PaletteLutBaker.Ladder(input, ColourMath.ToLab(input.Colours), ColourMath.ToLab(input.ValueRamp));
            paletteSha256 = ColourMath.PaletteSha256(ColourList());
            using (var sha = System.Security.Cryptography.SHA256.Create())
                lutSha256 = BitConverter.ToString(sha.ComputeHash(lut)).Replace("-", "").ToLowerInvariant();
            ReleaseTextures();
#if UNITY_EDITOR
            UnityEditor.EditorUtility.SetDirty(this);
#endif
        }

        /// <summary>Point-sampled size^3 RGBA8 table: (index a, index b, ratio of b, 1).</summary>
        public Texture3D LutTexture { get { EnsureTextures(); return m_LutTexture; } }
        /// <summary>256x1 RGBA8 strip of sRGB-encoded palette bytes; alpha holds index / 255.</summary>
        public Texture2D PaletteTexture { get { EnsureTextures(); return m_PaletteTexture; } }

        void EnsureTextures()
        {
            if (!IsBaked) throw new InvalidOperationException("PaletteProfile '" + profileId + "' has no baked LUT (run Bake)");
            if (m_LutTexture != null && m_PaletteTexture != null && ReferenceEquals(m_TextureLutSha, lutSha256) && ReferenceEquals(m_TexturePaletteSha, paletteSha256)) return;
            ReleaseTextures();
            m_LutTexture = new Texture3D(lutSize, lutSize, lutSize, GraphicsFormat.R8G8B8A8_UNorm, TextureCreationFlags.None)
            { name = "PixelLut_" + profileId, filterMode = FilterMode.Point, wrapMode = TextureWrapMode.Clamp, hideFlags = HideFlags.HideAndDontSave };
            m_LutTexture.SetPixelData(lut, 0); m_LutTexture.Apply(false, true);
            var strip = new byte[PaletteTextureWidth * 4];
            for (int i = 0; i < colours.Length && i < PaletteTextureWidth; i++)
            { strip[i * 4] = colours[i].r; strip[i * 4 + 1] = colours[i].g; strip[i * 4 + 2] = colours[i].b; strip[i * 4 + 3] = (byte)i; }
            m_PaletteTexture = new Texture2D(PaletteTextureWidth, 1, GraphicsFormat.R8G8B8A8_UNorm, TextureCreationFlags.None)
            { name = "PixelPalette_" + profileId, filterMode = FilterMode.Point, wrapMode = TextureWrapMode.Clamp, hideFlags = HideFlags.HideAndDontSave };
            m_PaletteTexture.SetPixelData(strip, 0); m_PaletteTexture.Apply(false, true);
            m_TextureLutSha = lutSha256; m_TexturePaletteSha = paletteSha256;
        }

        void ReleaseTextures()
        {
            if (m_LutTexture != null) DestroyImmediate(m_LutTexture);
            if (m_PaletteTexture != null) DestroyImmediate(m_PaletteTexture);
            m_LutTexture = null; m_PaletteTexture = null; m_TextureLutSha = null; m_TexturePaletteSha = null;
        }

        void OnDisable() => ReleaseTextures();
    }

    /// <summary>Dither mask textures built from mask ids ("bayer4", "bayer8", "cluster8", "bluenoise16", ...): the mask is data.</summary>
    public static class PixelDitherMaskCache
    {
        static readonly Dictionary<string, Texture2D> s_Masks = new Dictionary<string, Texture2D>();

        public static Texture2D Get(string id)
        {
            if (s_Masks.TryGetValue(id, out var tex) && tex != null) return tex;
            int[] ranks = DitherMasks.Create(id, out int size);
            byte[] bytes = DitherMasks.ToThresholdBytes(ranks);
            // DitherMasks are row-major with row 0 at the top; textures have row 0 at the bottom.
            var flipped = new byte[bytes.Length];
            for (int y = 0; y < size; y++) Array.Copy(bytes, y * size, flipped, (size - 1 - y) * size, size);
            tex = new Texture2D(size, size, GraphicsFormat.R8_UNorm, TextureCreationFlags.None)
            { name = "PixelDitherMask_" + id, filterMode = FilterMode.Point, wrapMode = TextureWrapMode.Repeat, hideFlags = HideFlags.HideAndDontSave };
            tex.SetPixelData(flipped, 0); tex.Apply(false, true);
            s_Masks[id] = tex;
            return tex;
        }

        public static void Clear()
        {
            foreach (var t in s_Masks.Values) if (t != null) UnityEngine.Object.DestroyImmediate(t);
            s_Masks.Clear();
        }
    }
}
